<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card" style="max-width:700px;margin:0 auto;"><div class="card-header"><h1>Checkout</h1><p>Review your order and place it.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<?php if(!$has_cart && !$successMsg):?><p class="muted">Cart is empty. <a href="<?php echo e(url_for('customer','browse'));?>">Browse</a></p><?php elseif($has_cart):?><table class="data-table"><tr><th>Product</th><th>Qty</th><th>Price</th><th>Subtotal</th></tr><?php foreach($_SESSION['cart'] as $it):$sub=(float)$it['price']*(int)$it['qty'];?><tr><td><?php echo e($it['name']);?></td><td><?php echo e($it['qty']);?></td><td>TK <?php echo e(number_format((float)$it['price'],2));?></td><td>TK <?php echo e(number_format($sub,2));?></td></tr><?php endforeach;?><tr><th colspan="3" style="text-align:right;">Total</th><th>TK <?php echo e(number_format($total,2));?></th></tr></table><form method="post" action="<?php echo e(url_for('customer','checkout'));?>" style="margin-top:18px;"><?php echo csrf_field();?><button class="btn btn-primary btn-block" data-confirm="Place this order?">Place Order (Cash on Delivery)</button></form><?php endif;?></div>
<?php if($orders):?><div class="card"><div class="card-header"><h2>Your Recent Orders</h2></div><table class="data-table"><tr><th>ID</th><th>Total</th><th>Status</th><th>Date</th></tr><?php foreach($orders as $o):?><tr><td>#<?php echo e($o['id']);?></td><td>TK <?php echo e(number_format((float)$o['total_amount'],2));?></td><td><?php echo e($o['delivery_status']);?></td><td class="small"><?php echo e($o['created_at']);?></td></tr><?php endforeach;?></table></div><?php endif;?>
